import "./editor";
import "./energy-plan/card";
import "./energy-monitor/card";
import "./nas";
import "./energy-cards/card";
import { MushroomEnergyLogCard } from "./energy-cards/energy-log";
import "./energy-cards/workflow-editor";
import { MushroomWorkflowCard } from "./energy-cards/workflow";
import { MushroomWeatherAdvancedCard } from "./weather-advanced/card";
import { MushroomAirQualityCard } from "./air-quality-card";
import { MushroomTodoCard } from "./todo-card";
import { MushroomCarAdvancedCard } from "./car-advanced/card";
import { CATALOG, LEGACY_ALIASES, PUBLIC_CATALOG } from "./catalog";
import { MushroomAdditionCard } from "./card";
import { MushroomMiniGraphCard } from "./mini-graph";
import { MushroomAreaAdvancedCard } from "./area-advanced";
import { MUSHROOM_AREA_TAG, MushroomAreaCard } from "./area-mushroom";
import type { AdditionConfig, CatalogItem, HomeAssistant } from "./types";
import { createStubConfig } from "./stub";
import { version as VERSION } from "../package.json";

for (const item of CATALOG) {
  if (!customElements.get(item.tag)) {
    if (item.upstreamId === "car_advanced") {
      customElements.define(item.tag, MushroomCarAdvancedCard);
      continue;
    }
    if (item.upstreamId === "todo") {
      customElements.define(item.tag, MushroomTodoCard);
      continue;
    }
    if (item.upstreamId === "energy_log") {
      customElements.define(item.tag, MushroomEnergyLogCard);
      continue;
    }
    if (item.upstreamId === "air_quality") {
      customElements.define(item.tag, MushroomAirQualityCard);
      continue;
    }
    if (item.upstreamId === "weather_advanced") {
      customElements.define(item.tag, MushroomWeatherAdvancedCard);
      continue;
    }
    if (item.upstreamId === "energy_entityworkflow") {
      customElements.define(item.tag, MushroomWorkflowCard);
      continue;
    }
    if (item.upstreamId === "area_card_advanced") {
      customElements.define(item.tag, MushroomAreaAdvancedCard);
      continue;
    }
    if (item.upstreamId === "mini_graph_card") {
      customElements.define(item.tag, MushroomMiniGraphCard);
      continue;
    }
    const descriptor = item;
    class RegisteredAdditionCard extends MushroomAdditionCard {
      protected descriptor: CatalogItem = descriptor;

      public static getStubConfig(
        hass?: HomeAssistant,
        entities: string[] = [],
        entitiesFallback: string[] = [],
      ): AdditionConfig {
        return createStubConfig(descriptor, hass, entities, entitiesFallback);
      }
    }
    customElements.define(item.tag, RegisteredAdditionCard);
  }
}

// Keep saved configurations working without offering a second Area card.
if (!customElements.get(MUSHROOM_AREA_TAG)) customElements.define(MUSHROOM_AREA_TAG, MushroomAreaCard);

for (const alias of LEGACY_ALIASES) {
  if (customElements.get(alias.tag)) continue;
  const descriptor = PUBLIC_CATALOG.find((item) => item.upstreamId === alias.targetId);
  if (!descriptor) throw new Error(`Missing alias target ${alias.targetId}.`);
  const aliasDescriptor = descriptor;
  const defaultVariant = alias.variant;
  class LegacyAdditionAlias extends MushroomAdditionCard {
    protected descriptor: CatalogItem = aliasDescriptor;

    public static getStubConfig(
      hass?: HomeAssistant,
      entities: string[] = [],
      entitiesFallback: string[] = [],
    ): AdditionConfig {
      const config = createStubConfig(aliasDescriptor, hass, entities, entitiesFallback);
      if (defaultVariant === "divider-title") {
        return {
          ...config,
          type: `custom:${alias.tag}`,
          entity: undefined,
          variant: defaultVariant,
          name: "Title",
          navigation_path: "",
          tap_action: { action: "none" },
        };
      }
      if (defaultVariant === "divider-subtitle") {
        return {
          ...config,
          type: `custom:${alias.tag}`,
          entity: undefined,
          variant: defaultVariant,
          name: "Subtitle",
          tap_action: { action: "none" },
        };
      }
      return {
        ...config,
        type: `custom:${alias.tag}`,
        variant: defaultVariant,
        show_forecast: alias.tag === "mushroom-addition-card-weather-ulm"
          ? false
          : config.show_forecast,
      };
    }

    public setConfig(config: AdditionConfig): void {
      super.setConfig({ ...config, variant: config.variant ?? defaultVariant });
    }
  }
  customElements.define(alias.tag, LegacyAdditionAlias);
}

window.customCards = window.customCards || [];
// Home Assistant retains this array when its picker module loads.
const removedPickerTags = new Set([
  MUSHROOM_AREA_TAG,
  "mushroom-addition-energy-insights",
  "mushroom-addition-energy-plan-actual",
  "mushroom-addition-battery-activity",
  "mushroom-addition-electricity-cost-timeline",
]);
for (let index = window.customCards.length - 1; index >= 0; index--) {
  if (removedPickerTags.has(window.customCards[index].type)) window.customCards.splice(index, 1);
}
const existing = new Set(window.customCards.map((card) => card.type));
for (const item of CATALOG) {
  if (existing.has(item.tag)) continue;
  window.customCards.push({
    type: item.tag,
    name: `Mushroom Addition: ${item.name}`,
    description: item.description,
    preview: false,
    documentationURL: "https://github.com/snfx-johaver/mushroom-addition",
  });
}

console.info(
  `%c MUSHROOM ADDITION %c ${VERSION} · ${CATALOG.length} components `,
  "color: white; background: #03a9f4; font-weight: 700;",
  "color: #03a9f4; background: white; font-weight: 700;",
);

export { CATALOG } from "./catalog";
export type { AdditionConfig } from "./types";
export type { EnergyLogConfig, EnergyLogCategory, EnergyLogSource, EnergyLogEntry } from "./energy-cards/energy-log-config";
export type { EnergyPlanConfig, EnergyPlanOptions, PlanRow, PlanMetric, PlanPeriod } from "./energy-plan/config";
export type { MonitorConfig, MonitorOptions, BaselineSource } from "./energy-monitor/config";
export type { WeatherAdvancedOptions } from "./weather-advanced/config";
export type { SmartSavingConfig } from "./energy-cards/types";
export type { WorkflowConfig } from "./energy-cards/workflow-config";
export type {
  CardConfig as NasCardConfig, NasSource, ManualVolumeConfig,
  ManualDriveConfig, ManualContainerConfig,
} from "./nas/config";
