export const remoteOptionTranslations: Record<string, Record<string, string>> = Object.fromEntries(
  Object.entries(rows).map(([locale, row]) => {
    const values = row.split("|");
    if (values.length !== keys.length) throw new Error(`Invalid ${locale} remote option row: ${values.length}/${keys.length}`);
    const catalog = Object.fromEntries(keys.map((key, index) => [key, values[index]]));
    for (const [key, value, unit] of [
      ["option.pause30", 30, "second"], ["option.pause60", 1, "minute"],
      ["option.pause300", 5, "minute"], ["option.pause900", 15, "minute"], ["option.pause3600", 1, "hour"],
    ] as const) {
      catalog[key] = new Intl.NumberFormat(locale, { style: "unit", unit, unitDisplay: "long" }).format(value);
    }
    catalog["option.cpu_percent"] = `${commonTranslations[locale]["ui.cpu"]} (%)`;
    catalog["option.memory_percent"] = `${commonTranslations[locale]["ui.memory"]} (%)`;
    return [locale, catalog];
  }),
);
